import{_ as e,o as d,c as s,a2 as a}from"./chunks/framework.CWWEQfK7.js";const _=JSON.parse('{"title":"配置加载与覆盖：确认最终生效的值","description":"理清默认值、环境变量和数据库运行时设置的优先级，并判断修改何时需要重启 API 或 Worker。","frontmatter":{"page_id":"configuration-loading-overrides","title":"配置加载与覆盖：确认最终生效的值","description":"理清默认值、环境变量和数据库运行时设置的优先级，并判断修改何时需要重启 API 或 Worker。"},"headers":[],"relativePath":"configuration/loading-and-overrides.md","filePath":"configuration/loading-and-overrides.md","lastUpdated":1786290726000}'),i={name:"configuration/loading-and-overrides.md"};function o(r,t,n,c,l,p){return d(),s("div",null,[...t[0]||(t[0]=[a(`<h1 id="配置加载与覆盖-确认最终生效的值" tabindex="-1">配置加载与覆盖：确认最终生效的值 <a class="header-anchor" href="#配置加载与覆盖-确认最终生效的值" aria-label="Permalink to &quot;配置加载与覆盖：确认最终生效的值&quot;">​</a></h1><p>同一个设置可能同时出现在默认值、<code>.env</code>、进程环境和数据库中。本页说明最终值从哪里来，以及修改后何时生效。</p><h2 id="先区分两类设置" tabindex="-1">先区分两类设置 <a class="header-anchor" href="#先区分两类设置" aria-label="Permalink to &quot;先区分两类设置&quot;">​</a></h2><p>Ershu 的后端设置分为两类：</p><ol><li><strong>启动设置</strong>：由设置类在进程内创建一次并缓存。修改环境变量后，需要重启对应进程。</li><li><strong>可在线覆盖设置</strong>：先读取环境值，再允许数据库中 <code>runtime.&lt;name&gt;</code> 这一行覆盖。服务刷新运行时设置后，新操作会使用新值。</li></ol><p>数据库覆盖不是对 <code>.env</code> 的改写。删除覆盖行后，设置会回到进程启动时读取的环境值，而不是恢复某个额外副本。</p><h2 id="优先级从低到高" tabindex="-1">优先级从低到高 <a class="header-anchor" href="#优先级从低到高" aria-label="Permalink to &quot;优先级从低到高&quot;">​</a></h2><table tabindex="0"><thead><tr><th>优先级</th><th>来源</th><th>说明</th></tr></thead><tbody><tr><td>1</td><td>设置类默认值</td><td>只在没有其他来源时使用</td></tr><tr><td>2</td><td><code>.env</code></td><td>设置类声明读取名为 <code>.env</code> 的文件</td></tr><tr><td>3</td><td>进程环境变量</td><td>部署平台注入的值覆盖同名 <code>.env</code> 值</td></tr><tr><td>4</td><td>数据库运行时设置</td><td>仅适用于已登记的运行时设置；键名为 <code>runtime.&lt;name&gt;</code></td></tr></tbody></table><p>API 的 <code>get_api_settings()</code> 和 Core 的 <code>get_settings()</code> 都使用进程内缓存。因此，修改非运行时环境变量，例如 <code>DATABASE_URL</code>、<code>REDIS_URL</code>、<code>CORS_ORIGINS</code> 或任何密钥后，必须重启使用它的进程。</p><h2 id="api-自己允许在线覆盖哪些值" tabindex="-1">API 自己允许在线覆盖哪些值 <a class="header-anchor" href="#api-自己允许在线覆盖哪些值" aria-label="Permalink to &quot;API 自己允许在线覆盖哪些值&quot;">​</a></h2><p>API 进程会读取 10 项 Core 运行时设置，再增加 1 项自己的聊天流式票据时长。</p><table tabindex="0"><thead><tr><th>设置名</th><th>环境变量</th><th>允许值</th><th>新值用于</th></tr></thead><tbody><tr><td><code>run_queue_lease_timeout_seconds</code></td><td><code>RUN_QUEUE_LEASE_TIMEOUT_SECONDS</code></td><td>300 至 86400</td><td>新的恢复扫描和心跳间隔</td></tr><tr><td><code>analysis_run_retention_count</code></td><td><code>ANALYSIS_RUN_RETENTION_COUNT</code></td><td>1 至 10000</td><td>任务完成或维护清理时的项目历史保留量</td></tr><tr><td><code>search_index_batch_size</code></td><td><code>SEARCH_INDEX_BATCH_SIZE</code></td><td>100 至 20000</td><td>新的索引重建批次</td></tr><tr><td><code>git_command_timeout_seconds</code></td><td><code>GIT_COMMAND_TIMEOUT_SECONDS</code></td><td>10 至 3600</td><td>后续 Git 命令和缓存锁等待</td></tr><tr><td><code>repository_storage_path</code></td><td><code>REPOSITORY_STORAGE_PATH</code></td><td>非空字符串，最多 255 个字符</td><td>后续仓库缓存访问</td></tr><tr><td><code>trusted_local_paths</code></td><td><code>TRUSTED_LOCAL_PATHS</code></td><td>最多 50 个字符串</td><td>后续本地工作区授权</td></tr><tr><td><code>allow_dev_open_local_repository_paths</code></td><td><code>ALLOW_DEV_OPEN_LOCAL_REPOSITORY_PATHS</code></td><td>布尔值</td><td>后续本地工作区授权</td></tr><tr><td><code>git_allowed_hosts</code></td><td><code>GIT_ALLOWED_HOSTS</code></td><td>最多 50 个字符串</td><td>后续远程仓库地址检查</td></tr><tr><td><code>allow_insecure_git_urls</code></td><td><code>ALLOW_INSECURE_GIT_URLS</code></td><td>布尔值</td><td>后续仓库地址检查</td></tr><tr><td><code>allow_file_git_urls</code></td><td><code>ALLOW_FILE_GIT_URLS</code></td><td>布尔值</td><td>后续仓库地址检查</td></tr><tr><td><code>stream_ticket_expire_seconds</code></td><td><code>STREAM_TICKET_EXPIRE_SECONDS</code></td><td>30 至 3600</td><td>新签发的聊天流式票据</td></tr></tbody></table><p>这里的“后续”很重要。例如，调整仓库路径不会移动现有缓存，调整票据时长也不会改写已签发票据。</p><h2 id="管理接口为什么会显示-48-项" tabindex="-1">管理接口为什么会显示 48 项 <a class="header-anchor" href="#管理接口为什么会显示-48-项" aria-label="Permalink to &quot;管理接口为什么会显示 48 项&quot;">​</a></h2><p>管理员接口 <code>GET /api/v1/admin/system-settings</code> 汇总三组定义：</p><ul><li>10 项 Core 运行时设置；</li><li>37 项 Worker 运行时设置；</li><li>1 项 API 运行时设置。</li></ul><p>API 负责校验并保存全部 48 项，也会在返回值中给出 <code>environment_value</code>、当前 <code>value</code> 和 <code>source</code>。但 API 进程只把 Core 与 API 定义应用到自己；Worker 必须由自己的刷新流程读取 Core 与 Worker 定义。看到管理接口保存成功，不代表每个正在运行的 Worker 已经刷新。</p><p>管理员可以通过以下三个端点管理覆盖：</p><table tabindex="0"><thead><tr><th>操作</th><th>端点</th><th>结果</th></tr></thead><tbody><tr><td>读取</td><td><code>GET /api/v1/admin/system-settings</code></td><td>返回所有定义、环境值、当前值和来源</td></tr><tr><td>更新</td><td><code>PATCH /api/v1/admin/system-settings</code></td><td>校验后写入数据库，并记录审计日志</td></tr><tr><td>重置</td><td><code>DELETE /api/v1/admin/system-settings/{name}</code></td><td>删除该设置的数据库覆盖，回到环境值</td></tr></tbody></table><p>这些端点只允许管理员账号访问。传入未知名称、错误类型、越界整数或过长列表时，请求会以输入错误结束，不会保存一半有效、一半无效的含糊状态。</p><h2 id="修改后多久生效" tabindex="-1">修改后多久生效 <a class="header-anchor" href="#修改后多久生效" aria-label="Permalink to &quot;修改后多久生效&quot;">​</a></h2><p>API 在启动时刷新一次，之后每 30 秒读取一次数据库覆盖。管理接口在写入或删除后会立即重新读取并返回当前状态。因此，API 侧的新操作通常能立即看到刚保存的 Core/API 值；其他 API 实例最迟在下一次正常刷新后看到。</p><p>周期刷新失败时，API 会记录错误并继续下一轮，不会主动退出。数据库里如果被外部工具写入无法解码或越界的值，刷新会失败；应通过管理接口修复或删除对应 <code>runtime.&lt;name&gt;</code> 行。</p><p>Worker 的生效时间由 Worker 自己的刷新点决定。不要用 API 的 30 秒周期推断 Worker 一定在相同时间更新。</p><h2 id="用返回值确认谁在生效" tabindex="-1">用返回值确认谁在生效 <a class="header-anchor" href="#用返回值确认谁在生效" aria-label="Permalink to &quot;用返回值确认谁在生效&quot;">​</a></h2><p>更新后，再读取管理接口中的目标项：</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;git_command_timeout_seconds&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;env_name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;GIT_COMMAND_TIMEOUT_SECONDS&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;value&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">180</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;environment_value&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">120</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;source&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;database&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>上面只展示响应字段含义，不是本地执行结果。判断规则如下：</p><ul><li><code>source</code> 为 <code>environment</code>：当前没有数据库覆盖，<code>value</code> 应与 <code>environment_value</code> 相同；</li><li><code>source</code> 为 <code>database</code>：数据库覆盖正在生效，两个值可以不同；</li><li>重置后再次读取：<code>source</code> 应回到 <code>environment</code>；</li><li>修改非运行时环境变量后：只有重启对应进程，缓存设置才会重建。</li></ul><h2 id="源码位置" tabindex="-1">源码位置 <a class="header-anchor" href="#源码位置" aria-label="Permalink to &quot;源码位置&quot;">​</a></h2><ul><li><code>core/src/ershu/core/config.py</code>：<code>.env</code> 声明、Core 设置和缓存入口。</li><li><code>core/src/ershu/services/runtime_settings.py</code>：Core 运行时定义、数据库键名、值校验、刷新和覆盖应用。</li><li><code>core/src/ershu/services/worker_runtime_contract.py</code>：37 项 Worker 管理契约。</li><li><code>api/src/ershu/api/runtime_settings.py</code>：API 设置、流式票据定义和 API 刷新入口。</li><li><code>api/src/ershu/api/services/system_settings.py</code>：48 项设置的汇总、来源标记、更新与重置。</li><li><code>api/src/ershu/api/routes/system_settings.py</code>：管理员端点与权限依赖。</li><li><code>api/src/ershu/api_main.py</code>：启动刷新和每 30 秒一次的 API 刷新循环。</li><li><code>worker/src/ershu/workers/runtime_settings.py</code>：Worker 应用 Core 与 Worker 运行时设置的入口。</li></ul>`,31)])])}const u=e(i,[["render",o]]);export{_ as __pageData,u as default};
